unsigned int BmPlus_IBM_VGA_8x16_otb_len = 24084;

inline void drawChar(cv::Mat& img,
              unsigned char c,
              int x,
              int y,
              cv::Scalar color,
              int scale = 1)
{
    const uint8_t* glyph = BmPlus_IBM_VGA_8x16_otb[c];

    for (int row = 0; row < 16; row++)
    {
        uint8_t bits = glyph[row];

        for (int col = 0; col < 8; col++)
        {
            if (bits & (1 << (7-col)))
            {
                cv::rectangle(
                    img,
                    cv::Rect(
                        x + col*scale,
                        y + row*scale,
                        scale,
                        scale),
                    color,
                    cv::FILLED);
            }
        }
    }
}

inline void drawText(cv::Mat& img,
              const std::string& txt,
              int x,
              int y,
              cv::Scalar color,
              int scale)
{
    int cursor = x;

    for(char c : txt)
    {
        drawChar(img,
                 c,
                 cursor,
                 y,
                 color,
                 scale);

        cursor += 8*scale;
    }
}

inline void drawTextOutline(
    cv::Mat& img,
    const std::string& txt,
    int x,
    int y,
    cv::Scalar fg,
    cv::Scalar bg,
    int scale)
{
    for(int dy=-1;dy<=1;dy++)
    {
        for(int dx=-1;dx<=1;dx++)
        {
            if(dx==0 && dy==0)
                continue;

            drawText(img,
                     txt,
                     x+dx*scale,
                     y+dy*scale,
                     bg,
                     scale);
        }
    }

    drawText(img,
             txt,
             x,
             y,
             fg,
             scale);
}